		TripleTerm inner = Values.tripleTerm(Values.iri("urn:retained:subject"),
				Values.iri("urn:retained:predicate"), Values.literal("a retained nested literal"));
		TripleTerm outer = Values.tripleTerm(Values.bnode("retained-outer"),
				Values.iri("urn:retained:outer-predicate"), inner);
		valueStore.startTransaction(true);
		long outerId = valueStore.storeValue(outer);
