	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	public void testDirectDictionarySnapshotKeepsRetiredAndReusedIdSemantics(boolean rollbackFirst) throws Exception {
		long id = storeBNodes("strict-original")[0];
		Value original = Values.bnode("strict-original");
		Value replacement = Values.bnode("strict-replacement");
		try (ValueStore.ReadSnapshotReservation reservation = valueStore.reserveReadSnapshot();
				ValueStore.ReadSnapshot snapshot = reservation.start()) {
			assertEquals(original, valueStore.getValue(snapshot, id));
			assertEquals(id, valueStore.getId(snapshot, original));
			if (rollbackFirst) {
				valueStore.startTransaction(true);
				valueStore.gcIds(Set.of(id), new HashSet<>());
				valueStore.storeValue(original);
				valueStore.rollback();
				assertEquals("Rollback must restore the current dictionary mapping", id, valueStore.getId(original));
				assertEquals(id, valueStore.getId(snapshot, original));
			}

			CountDownLatch revisionCollected = trackRevisionCollection(valueStore.getLazyValue(id));
			retireValues(Set.of(id));
			awaitRevisionCollection(revisionCollected);
			evictRetiredValues();
			assertNull("The current dictionary has physically removed the original bytes", valueStore.getValue(id));
			assertEquals("The committed writer may reuse the ID outside the strict snapshot", id,
					storeBNodes("strict-replacement")[0]);

			assertEquals(replacement, valueStore.getValue(id));
			assertEquals(LmdbValue.UNKNOWN_ID, valueStore.getId(original));
			assertEquals(original, valueStore.getValue(snapshot, id));
			assertEquals("Reverse lookup must use the captured dictionary generation", id,
					valueStore.getId(snapshot, original));
			assertEquals("The replacement must not appear in the older dictionary", LmdbValue.UNKNOWN_ID,
					valueStore.getId(snapshot, replacement));
			assertEquals(original, valueStore.getLazyValue(snapshot, id));
		}
	}

	@Test
	public void testDirectDictionarySnapshotReportsValueStoreGrowthConflict() throws Exception {
		valueStore.close();
		valueStore = new ValueStore(new File(dataDir, "strict-growth-values"),
				new LmdbStoreConfig().setValueDBSize(1024L * 1024).setAutoGrow(true));
		long id = storeBNodes("strict-growth-original")[0];
		Value original = Values.bnode("strict-growth-original");
		try (ValueStore.ReadSnapshotReservation reservation = valueStore.reserveReadSnapshot();
				ValueStore.ReadSnapshot snapshot = reservation.start()) {
			assertEquals(original, valueStore.getValue(snapshot, id));
			valueStore.startTransaction(true);
			long largeId = valueStore.storeValue(Values.literal("strict-growth".repeat(200_000)));
			valueStore.commit();
			assertNotNull("The large value must have been written in the resized dictionary",
					valueStore.getValue(largeId));

			LmdbSailStore.MapResizeConflictException valueConflict = assertThrows(
					LmdbSailStore.MapResizeConflictException.class, () -> valueStore.getValue(snapshot, id));
			assertEquals(LmdbSailStore.MapResizeKind.VALUE_STORE, valueConflict.kind());
			LmdbSailStore.MapResizeConflictException lookupConflict = assertThrows(
					LmdbSailStore.MapResizeConflictException.class, () -> valueStore.getId(snapshot, original));
			assertEquals(LmdbSailStore.MapResizeKind.VALUE_STORE, lookupConflict.kind());
		}
	}

	@ParameterizedTest
	@ValueSource(strings = { "iri", "literal", "nested" })
	public void testSnapshotLookupCapturesEscapedLazyInputBeforeNativeLocks(String kind) throws Exception {
		valueStore.close();
		CountDownLatch resolutionEntered = new CountDownLatch(1);
		CountDownLatch releaseResolution = new CountDownLatch(1);
		CountDownLatch resolutionFinished = new CountDownLatch(1);
		AtomicReference<LmdbValue> heldValue = new AtomicReference<>();
		LmdbStoreConfig config = new LmdbStoreConfig().setInlineLiterals(false);
		valueStore = new ValueStore(new File(dataDir, "lookup-input-values"), config) {
			@Override
			boolean resolveValue(long id, LmdbValue value, ValueStoreRevision revision) {
				if (value == heldValue.get()) {
					assertTrue("The naked getter must own the escaped value monitor", Thread.holdsLock(value));
					resolutionEntered.countDown();
					try {
						assertTrue("Input capture must release the competing lazy getter",
								releaseResolution.await(5, TimeUnit.SECONDS));
					} catch (InterruptedException e) {
						Thread.currentThread().interrupt();
						throw new SailException(e);
					}
				}
				return super.resolveValue(id, value, revision);
			}
		};
		IRI subject = Values.iri("urn:lookup-input:subject");
		IRI predicate = Values.iri("urn:lookup-input:predicate");
		Literal literal = Values.literal("custom datatype input", Values.iri("urn:lookup-input:datatype"));
		Value expected = switch (kind) {
		case "iri" -> subject;
		case "literal" -> literal;
		case "nested" -> Values.tripleTerm(subject, predicate, Values.tripleTerm(subject, predicate, literal));
		default -> throw new IllegalArgumentException(kind);
		};
		ExecutorService executor = Executors.newSingleThreadExecutor();
		try (TripleStore triples = new TripleStore(new File(dataDir, "lookup-input-triples"), config, valueStore)) {
			valueStore.startTransaction(true);
			long id = valueStore.storeValue(expected);
			valueStore.commit();
			LmdbValue escaped;
			try (TxnManager.ReaderReservation tripleReservation = triples.getTxnManager().reserveReadTxn(false);
					Txn tripleTxn = tripleReservation.startPinned(triples::getDataRevision);
					ValueStore.ReadSnapshotReservation oldReservation = valueStore.reserveReadSnapshot();
					ValueStore.ReadSnapshot oldSnapshot = oldReservation.start(tripleTxn)) {
				oldSnapshot.retainStableIds(tripleTxn);
				escaped = valueStore.getLazyValue(oldSnapshot, id);
				heldValue.set(escaped);
				assertEquals("Same-revision lookup must use the known ID without lexical capture", id,
						valueStore.getId(oldSnapshot, escaped));
				assertEquals("The ID fast path must leave the escaped value unresolved", 1L,
						resolutionEntered.getCount());
			}
			valueStore.startTransaction(true);
			valueStore.rollback();
			try (TxnManager.ReaderReservation tripleReservation = triples.getTxnManager().reserveReadTxn(false);
					Txn tripleTxn = tripleReservation.startPinned(triples::getDataRevision);
					ValueStore.ReadSnapshotReservation reservation = valueStore.reserveReadSnapshot();
					ValueStore.ReadSnapshot snapshot = reservation.start(tripleTxn)) {
				snapshot.retainStableIds(tripleTxn);
				assertNotEquals("Rollback must rotate the captured dictionary revision",
						escaped.getValueStoreRevision(), snapshot.revision());
				Future<?> getter = executor.submit(() -> {
					try {
						escaped.init();
					} finally {
						resolutionFinished.countDown();
					}
				});
				assertTrue("The real naked lazy getter must start first",
						resolutionEntered.await(5, TimeUnit.SECONDS));
				AtomicBoolean firstCapture = new AtomicBoolean(true);
				Runnable beforeGetter = () -> {
					assertFalse("Snapshot input getters must run outside the native transaction monitor",
							Thread.holdsLock(snapshot.txnRef()));
					if (firstCapture.compareAndSet(true, false)) {
						assertFalse("Snapshot input capture must precede the native read barrier",
								valueStore.getTxnManager().lockManager().isReaderActive());
						releaseResolution.countDown();
						try {
							assertTrue("The naked getter must finish borrowing the newer paired view before capture",
									resolutionFinished.await(5, TimeUnit.SECONDS));
						} catch (InterruptedException e) {
							Thread.currentThread().interrupt();
							throw new SailException(e);
						}
					}
				};
				try {
					assertEquals(id, valueStore.getId(snapshot, guardedSnapshotInput(escaped, beforeGetter)));
				} finally {
					releaseResolution.countDown();
					getter.get(5, TimeUnit.SECONDS);
				}
				assertFalse("Lookup must actually capture the supplied lexical input", firstCapture.get());
				assertEquals(expected, escaped);
			}
		} finally {
			releaseResolution.countDown();
			executor.shutdownNow();
			assertTrue("Input lookup worker must finish", executor.awaitTermination(5, TimeUnit.SECONDS));
		}
	}

	private static Value guardedSnapshotInput(Value value, Runnable beforeGetter) {
		if (value instanceof IRI iri) {
			return new AbstractIRI() {
				@Override
				public String getNamespace() {
					beforeGetter.run();
					return iri.getNamespace();
				}

				@Override
				public String getLocalName() {
					beforeGetter.run();
					return iri.getLocalName();
				}
			};
		}
		if (value instanceof Literal literal) {
			return new AbstractLiteral() {
				@Override
				public String getLabel() {
					beforeGetter.run();
					return literal.getLabel();
				}

				@Override
				public Optional<String> getLanguage() {
					beforeGetter.run();
					return literal.getLanguage();
				}

				@Override
				public BaseDirection getBaseDirection() {
					beforeGetter.run();
					return literal.getBaseDirection();
				}

				@Override
				public IRI getDatatype() {
					beforeGetter.run();
					return (IRI) guardedSnapshotInput(literal.getDatatype(), beforeGetter);
				}

				@Override
				public CoreDatatype getCoreDatatype() {
					beforeGetter.run();
					return literal.getCoreDatatype();
				}
			};
		}
		if (value instanceof TripleTerm triple) {
			return new AbstractTripleTerm() {
				@Override
				public Resource getSubject() {
					beforeGetter.run();
					return (Resource) guardedSnapshotInput(triple.getSubject(), beforeGetter);
				}

				@Override
				public IRI getPredicate() {
					beforeGetter.run();
					return (IRI) guardedSnapshotInput(triple.getPredicate(), beforeGetter);
				}

				@Override
				public Value getObject() {
					beforeGetter.run();
					return guardedSnapshotInput(triple.getObject(), beforeGetter);
				}
			};
		}
		throw new IllegalArgumentException("Unsupported guarded input " + value.getType());
	}

	@Test
	public void testSharedLazyNestedValuesSurviveCrossThreadCloseAndReopen() throws Exception {
		ExecutorService executor = Executors.newSingleThreadExecutor();
		try {
			for (int cycle = 0; cycle < 3; cycle++) {
				TripleTerm inner = Values.tripleTerm(Values.iri("urn:shutdown:subject:" + cycle), RDF.TYPE,
						Values.literal("retained shutdown literal " + cycle));
				TripleTerm outer = Values.tripleTerm(Values.bnode("shutdown-outer-" + cycle), RDF.TYPE, inner);
				valueStore.startTransaction(true);
				long id = valueStore.storeValue(outer);
				valueStore.commit();
				LmdbTripleTerm held = (LmdbTripleTerm) valueStore.getLazyValue(id);
				ValueStore closingStore = valueStore;
				executor.submit(() -> {
					closingStore.close();
					closingStore.close();
					return null;
				}).get(10, TimeUnit.SECONDS);
				assertEquals(inner.getObject().stringValue(),
						executor.submit(() -> ((TripleTerm) held.getObject()).getObject().stringValue())
								.get(10, TimeUnit.SECONDS));
				assertEquals(inner, held.getObject());
				assertEquals(outer, held);
				valueStore = createValueStore();
				assertEquals(outer, valueStore.getValue(id));
			}
		} finally {
			executor.shutdownNow();
			assertTrue("Shutdown workers must finish", executor.awaitTermination(10, TimeUnit.SECONDS));
		}
	}

