	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	public void testReadyWriterValueDoesNotPublishIdDuringRollbackCleanup(boolean nested) throws Exception {
		valueStore.close();
		CountDownLatch nativeAborted = new CountDownLatch(1);
		CountDownLatch releaseCleanup = new CountDownLatch(1);
		AtomicBoolean pauseCleanup = new AtomicBoolean();
		valueStore = new ValueStore(new File(dataDir, "values"), new LmdbStoreConfig()) {
			@Override
			void rollbackRetiredIds() {
				if (pauseCleanup.compareAndSet(true, false)) {
					nativeAborted.countDown();
					try {
						assertTrue("The test must release the post-native-abort cleanup boundary",
								releaseCleanup.await(10, TimeUnit.SECONDS));
					} catch (InterruptedException e) {
						Thread.currentThread().interrupt();
						throw new SailException(e);
					}
				}
				super.rollbackRetiredIds();
			}
		};
		LmdbValue ready = readyWriterValue(nested);
		ExecutorService writer = Executors.newSingleThreadExecutor();
		Future<?> rollback = writer.submit(() -> {
			valueStore.startTransaction(true);
			valueStore.storeValue(ready);
			pauseCleanup.set(true);
			valueStore.rollback();
			return null;
		});
		try {
			assertTrue("The actual native abort must finish before its metadata cleanup is paused",
					nativeAborted.await(5, TimeUnit.SECONDS));
			assertEquals("An aborted ready value cannot publish its old ID while writer state is being cleared",
					LmdbValue.UNKNOWN_ID, valueStore.getId(ready));
			releaseCleanup.countDown();
			rollback.get(5, TimeUnit.SECONDS);
			assertEquals(LmdbValue.UNKNOWN_ID, valueStore.getId(ready));
		} finally {
			releaseCleanup.countDown();
			try {
				rollback.get(5, TimeUnit.SECONDS);
			} finally {
				writer.shutdownNow();
				assertTrue(writer.awaitTermination(5, TimeUnit.SECONDS));
			}
		}
	}

	private LmdbValue readyWriterValue(boolean nested) {
		LmdbBNode subject = valueStore.createBNode("ready-uncommitted-subject");
		return nested ? (LmdbValue) valueStore.createTripleTerm(subject,
				valueStore.createIRI("urn:ready-uncommitted:predicate"),
				valueStore.createLiteral("ready uncommitted nested payload",
						valueStore.createIRI("urn:ready:datatype")))
				: subject;
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	public void testReadyValueCapturedBeforeWriterSettlementUsesCompletedPublication(boolean commit) throws Exception {
		CountDownLatch identityCaptured = new CountDownLatch(1);
		CountDownLatch releaseIdentity = new CountDownLatch(1);
		AtomicReference<Thread> readerThread = new AtomicReference<>();
		AtomicBoolean pauseIdentity = new AtomicBoolean(true);
		LmdbBNode ready = new LmdbBNode(valueStore.getRevision(), "ready-captured-before-settlement") {
			@Override
			public InternalIdentity getInternalIdentity() {
				InternalIdentity captured = super.getInternalIdentity();
				if (Thread.currentThread() == readerThread.get() && pauseIdentity.compareAndSet(true, false)) {
					identityCaptured.countDown();
					try {
						assertTrue("The test must release the captured immutable model identity",
								releaseIdentity.await(10, TimeUnit.SECONDS));
					} catch (InterruptedException e) {
						Thread.currentThread().interrupt();
						throw new SailException(e);
					}
				}
				return captured;
			}
		};
		valueStore.startTransaction(true);
		long id = valueStore.storeValue(ready);
		ExecutorService reader = Executors.newSingleThreadExecutor();
		Future<Long> lookup = reader.submit(() -> {
			readerThread.set(Thread.currentThread());
			return valueStore.getId(ready);
		});
		try {
			assertTrue("The reader must capture the real writer-bound model before settlement",
					identityCaptured.await(5, TimeUnit.SECONDS));
			if (commit) {
				valueStore.commit();
			} else {
				valueStore.rollback();
			}
			releaseIdentity.countDown();
			assertEquals("The captured identity must be qualified after observing completed publication",
					commit ? id : LmdbValue.UNKNOWN_ID, (long) lookup.get(5, TimeUnit.SECONDS));
		} finally {
			releaseIdentity.countDown();
			valueStore.rollback();
			reader.shutdownNow();
			assertTrue(reader.awaitTermination(5, TimeUnit.SECONDS));
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	public void testFailedReadyWriterPublicationKeepsCommittedLookupAndAllowsNextWriter(boolean cleanupFails)
			throws Exception {
		valueStore.close();
		AtomicBoolean failCommit = new AtomicBoolean();
		AtomicBoolean failCleanup = new AtomicBoolean();
		valueStore = new ValueStore(new File(dataDir, "values"), new LmdbStoreConfig()) {
			@Override
			int commitWriteTransaction(long transaction) {
				if (failCommit.compareAndSet(true, false)) {
					mdb_txn_abort(transaction);
					return MDB_BAD_TXN;
				}
				return super.commitWriteTransaction(transaction);
			}

			@Override
			void rollbackRetiredIds() {
				if (failCleanup.compareAndSet(true, false)) {
					throw new SailException("Deliberate retired-ID cleanup failure after native consumption");
				}
				super.rollbackRetiredIds();
			}
		};
		LmdbValue ready = readyWriterValue(false);
		valueStore.startTransaction(true);
		valueStore.storeValue(ready);
		failCommit.set(true);
		failCleanup.set(cleanupFails);
		IOException failure = assertThrows(IOException.class, valueStore::commit);
		assertEquals(cleanupFails ? 1 : 0, failure.getSuppressed().length);
		ExecutorService reader = Executors.newSingleThreadExecutor();
		try {
			assertEquals("Native commit failure must not publish the ready input's aborted ID", LmdbValue.UNKNOWN_ID,
					(long) reader.submit(() -> valueStore.getId(ready)).get(5, TimeUnit.SECONDS));
			valueStore.startTransaction(true);
			long committedId = valueStore.storeValue(ready);
			valueStore.commit();
			assertEquals("Successful cleanup must release publication admission for the following writer", committedId,
					(long) reader.submit(() -> valueStore.getId(ready)).get(5, TimeUnit.SECONDS));
		} finally {
			valueStore.rollback();
			reader.shutdownNow();
			assertTrue(reader.awaitTermination(5, TimeUnit.SECONDS));
		}
	}

