	private void retireValues(Set<Long> ids) throws IOException {
		valueStore.startTransaction(true);
		Set<Long> pending = ids;
		while (!pending.isEmpty()) {
			Set<Long> next = new HashSet<>();
			valueStore.gcIds(pending, next);
			pending = next;
		}
		valueStore.commit();
	}

	private void evictRetiredValues() throws IOException {
		valueStore.forceEvictionOfValues();
		valueStore.startTransaction(true);
		valueStore.commit();
	}

	private CountDownLatch trackRevisionCollection(LmdbValue value) {
		return trackCollection(value.getValueStoreRevision());
	}

	private CountDownLatch trackCollection(Object referent) {
		CountDownLatch collected = new CountDownLatch(1);
		revisionCleaner.register(referent, collected::countDown);
		return collected;
	}

	private void awaitRevisionCollection(CountDownLatch collected) throws InterruptedException {
		awaitCollection(collected);
		// Both registrations use the registering thread's shared ConcurrentCleaner. A subsequent collection
		// barrier lets it finish the value store's cleanup actions for the previously collected revision.
		awaitCollection(trackCollection(new Object()));
	}

	private void awaitCollection(CountDownLatch collected) throws InterruptedException {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
		while (collected.getCount() != 0 && System.nanoTime() < deadline) {
			System.gc();
			collected.await(100, TimeUnit.MILLISECONDS);
		}
		assertEquals("The unreachable revision must be collected before checking reclamation", 0,
				collected.getCount());
	}

	@Test
	public void testGcValuesAfterRestart() throws Exception {
		Random random = new Random(1337);
		LmdbValue[] values = new LmdbValue[1000];
		valueStore.startTransaction(true);
		for (int i = 0; i < values.length; i++) {
			values[i] = valueStore.createLiteral("This is a random literal:" + random.nextLong());
			valueStore.storeValue(values[i]);
		}
		valueStore.commit();

		valueStore.startTransaction(true);
		Set<Long> ids = new HashSet<>();
		for (int i = 0; i < 30; i++) {
			ids.add(values[i].getInternalID());
		}
		valueStore.gcIds(ids, new HashSet<>());
		valueStore.commit();

		// close and recreate store
		valueStore.close();
		valueStore = createValueStore();

		valueStore.startTransaction(true);
		for (int i = 0; i < 30; i++) {
			LmdbValue value = valueStore.createLiteral("This is a random literal:" + random.nextLong());
			values[i] = value;
			valueStore.storeValue(value);
			// this ID should have been reused
			ids.remove(value.getInternalID());
		}
		valueStore.commit();

		assertEquals("IDs should have been reused", Collections.emptySet(), ids);
	}

