	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	public void testReferencedNestedTermCannotBeCollected(boolean commitReferences) throws Exception {
		IRI shared = Values.iri("urn:refcount:shared");
		TripleTerm inner = Values.tripleTerm(shared, shared, shared);
		TripleTerm outer = Values.tripleTerm(shared, shared, inner);
		valueStore.startTransaction(true);
		long innerId = valueStore.storeValue(inner);
		long outerId = valueStore.storeValue(outer);
		if (commitReferences) {
			valueStore.commit();
			valueStore.startTransaction(true);
		}

		Set<Long> nextIds = new HashSet<>();
		valueStore.gcIds(Collections.singleton(innerId), nextIds);
		assertTrue("A referenced nested term must keep its component references", nextIds.isEmpty());
		valueStore.commit();
		assertEquals(innerId, valueStore.getId(inner));
		assertEquals(outerId, valueStore.getId(outer));

		valueStore.startTransaction(true);
		valueStore.gcIds(Collections.singleton(outerId), nextIds);
		assertEquals(Collections.singleton(innerId), nextIds);
		Set<Long> componentIds = new HashSet<>();
		valueStore.gcIds(nextIds, componentIds);
		assertEquals(Collections.singleton(valueStore.getId(shared)), componentIds);
		valueStore.commit();
	}

