	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	public void testRepeatedRetirementCannotDeleteReusedId(boolean tripleTerm) throws Exception {
		Value original = tripleTerm ? Values.tripleTerm(RDF.TYPE, RDF.TYPE, Values.literal(1))
				: Values.bnode("original");
		Value replacement = tripleTerm ? Values.tripleTerm(RDF.TYPE, RDF.TYPE, Values.literal(2))
				: Values.bnode("replacement");
		valueStore.startTransaction(true);
		long originalId = valueStore.storeValue(original);
		valueStore.commit();
		long firstRevision = valueStore.getRevision().getRevisionId();
		valueStore.startTransaction(true);
		valueStore.gcIds(Collections.singleton(originalId), new HashSet<>());
		valueStore.commit();
		long laterRevision = valueStore.getRevision().getRevisionId();
		valueStore.startTransaction(true);
		valueStore.gcIds(Collections.singleton(originalId), new HashSet<>());
		valueStore.commit();

		valueStore.unusedRevisionIds.add(firstRevision);
		valueStore.forceEvictionOfValues();
		valueStore.startTransaction(true);
		valueStore.commit();
		valueStore.startTransaction(true);
		long replacementId = valueStore.storeValue(replacement);
		assertEquals("The earlier retirement makes this ID available for reuse", originalId, replacementId);
		valueStore.commit();
		valueStore.unusedRevisionIds.add(laterRevision);
		valueStore.forceEvictionOfValues();
		valueStore.startTransaction(true);
		valueStore.commit();
		assertEquals("A later duplicate retirement must not remove the new owner", replacement,
				valueStore.getValue(replacementId));
		assertEquals(replacementId, valueStore.getId(replacement));

		Value rolledBack = Values.bnode("after-empty-retirement-rollback");
		valueStore.startTransaction(true);
		assertEquals("A writer after empty reclamation must read the committed association", replacement,
				valueStore.getValue(replacementId));
		valueStore.storeValue(rolledBack);
		valueStore.rollback();
		assertEquals(LmdbValue.UNKNOWN_ID, valueStore.getId(rolledBack));
		assertEquals(replacement, valueStore.getValue(replacementId));

		Value committed = Values.bnode("after-empty-retirement-commit");
		valueStore.startTransaction(true);
		long committedId = valueStore.storeValue(committed);
		valueStore.commit();
		assertEquals(committed, valueStore.getValue(committedId));
		assertEquals(replacement, valueStore.getValue(replacementId));
	}

	@Test
	public void testLegacyCountsRebuiltFromActiveNestedTerms() throws Exception {
		IRI shared = Values.iri("urn:refcount:legacy-shared");
		TripleTerm inner = Values.tripleTerm(shared, shared, shared);
		valueStore.startTransaction(true);
		long innerId = valueStore.storeValue(inner);
		valueStore.storeValue(Values.tripleTerm(shared, shared, inner));
		Literal inlineObject = Values.literal(1);
		valueStore.storeValue(Values.tripleTerm(shared, shared, inlineObject));
		long inlineId = valueStore.getId(inlineObject);
		assertTrue("The fixture must exercise an inlined component", ValueIds.isInlined(inlineId));
		long retiredId = valueStore.storeValue(Values.tripleTerm(Values.bnode("retired"), shared, inner));
		valueStore.commit();
		valueStore.startTransaction(true);
		valueStore.gcIds(Collections.singleton(retiredId), new HashSet<>());
		valueStore.commit();
		long sharedId = valueStore.getId(shared);
		replaceLegacyRefCount(sharedId, 1);

		valueStore.close();
		valueStore = createValueStore();
		assertEquals("Duplicate component roles count separately, retired terms do not", 7L,
				persistedRefCount(sharedId));
		assertEquals("The active outer term references its inner term", 1L, persistedRefCount(innerId));
		assertEquals("Inlined components do not require a dictionary record", 1L, persistedRefCount(inlineId));
		assertNull(valueStore.getValue(retiredId));
	}

	private long persistedRefCount(long id) throws IOException {
		return valueStore.writeTransaction((stack, txn) -> {
			int countsDbi = openDatabaseWithTxn(txn, "ref_counts", 0);
			MDBVal key = MDBVal.calloc(stack);
			key.mv_data(valueStore.id2data(valueStore.idBuffer(stack), id).flip());
			MDBVal data = MDBVal.calloc(stack);
			return mdb_get(txn, countsDbi, key, data) == MDB_SUCCESS ? Varint.readUnsigned(data.mv_data()) : 0L;
		});
	}

	@Test
	public void testDamagedLegacyReferencesFailBeforeReclamation() throws Exception {
		IRI datatype = Values.iri("urn:refcount:missing-datatype");
		valueStore.startTransaction(true);
		long literalId = valueStore.storeValue(Values.literal("surviving literal", datatype));
		valueStore.commit();
		long datatypeId = valueStore.getId(datatype);
		replaceLegacyRefCount(datatypeId, 0);
		valueStore.startTransaction(true);
		valueStore.gcIds(Collections.singleton(datatypeId), new HashSet<>());
		valueStore.commit();
		assertNotNull("The retired record remains recoverable before opening", valueStore.getData(datatypeId));
		valueStore.close();

		for (int attempt = 0; attempt < 3; attempt++) {
			IOException failure = assertThrows(IOException.class, this::createValueStore);
			assertTrue(failure.getMessage(), failure.getMessage().contains("missing or retired"));
			inspectNativeStore(new File(dataDir, "values"), (stack, txn) -> {
				assertNativeRecordExists(stack, txn, datatypeId);
				assertNativeRecordExists(stack, txn, literalId);
				assertEquals(0L, nativeRefCount(stack, txn, datatypeId));
				assertMigrationMarkerAbsent(stack, txn);
				MDBStat stat = MDBStat.calloc(stack);
				E(mdb_stat(txn, openDatabaseWithTxn(txn, "unused_ids", 0), stat));
				assertEquals("Failed validation must retain the pending retired datatype", 1L, stat.ms_entries());
				return null;
			});
		}
	}

	@Test
	public void testLegacyRebuildMapFullAbortsAndRetriesAfterGrowth() throws Exception {
		valueStore.close();
		File constrainedDir = new File(dataDir, "constrained");
		LmdbStoreConfig config = new LmdbStoreConfig().setValueDBSize(1024 * 1024).setAutoGrow(false);
		valueStore = new ValueStore(constrainedDir, config);
		valueStore.startTransaction(true);
		long datatypeId = 0;
		for (int i = 0; i < 1024; i++) {
			IRI datatype = Values.iri("urn:legacy:namespace:" + i + ":datatype");
			valueStore.storeValue(Values.literal("stored literal " + i, datatype));
			datatypeId = valueStore.getId(datatype);
		}
		valueStore.commit();
		replaceLegacyRefCount(datatypeId, 17);
		// Consume capacity independently of dictionary insertion so this fixture exercises the rebuild's ordinary puts.
		int capacityDbi = valueStore.writeTransaction(
				(stack, txn) -> openDatabaseWithTxn(txn, "migration_capacity", MDB_CREATE));
		for (int filler = 0;; filler++) {
			int entry = filler;
			try {
				valueStore.writeTransaction((stack, txn) -> {
					MDBVal key = MDBVal.calloc(stack);
					key.mv_data(stack.malloc(Integer.BYTES).putInt(entry).flip());
					MDBVal data = MDBVal.calloc(stack);
					data.mv_data(stack.calloc(2048));
					E(mdb_put(txn, capacityDbi, key, data, 0));
					return null;
				});
			} catch (IOException full) {
				assertTrue(full.getMessage(), full.getMessage().contains("MDB_MAP_FULL"));
				break;
			}
		}
		valueStore.close();
		IOException failure = assertThrows(IOException.class, () -> new ValueStore(constrainedDir, config).close());
		assertTrue(failure.getMessage(),
				failure.getMessage().contains("Insufficient space to rebuild LMDB reference counts atomically"));
		long lastDatatypeId = datatypeId;
		inspectNativeStore(constrainedDir, (stack, txn) -> {
			assertEquals("A failed rebuild must preserve the old count", 17L,
					nativeRefCount(stack, txn, lastDatatypeId));
			assertMigrationMarkerAbsent(stack, txn);
			return null;
		});

		valueStore = new ValueStore(constrainedDir, config.setAutoGrow(true));
		assertEquals("Growth must retry and commit the complete reconstruction", 1L, persistedRefCount(datatypeId));
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	public void testLegacyPendingRetirementCannotDeleteActiveOwner(boolean tripleTerm) throws Exception {
		Value replacement = tripleTerm ? Values.tripleTerm(RDF.TYPE, RDF.TYPE, Values.literal(2))
				: Values.bnode("replacement");
		valueStore.startTransaction(true);
		long id = valueStore.storeValue(replacement);
		valueStore.commit();
		replaceLegacyRefCount(id, 17);
		// A legacy duplicate retirement can remain after this ID has been reused by an active new owner.
		valueStore.writeTransaction((stack, txn) -> {
			ByteBuffer pendingKey = stack.malloc(2 + 2 * Long.BYTES + 1);
			Varint.writeUnsigned(pendingKey, valueStore.getRevision().getRevisionId());
			valueStore.id2data(pendingKey, id);
			MDBVal key = MDBVal.calloc(stack);
			key.mv_data(pendingKey.flip());
			E(mdb_put(txn, openDatabaseWithTxn(txn, "unused_ids", 0), key, MDBVal.calloc(stack), 0));
			return null;
		});
		valueStore.close();

		IOException failure = assertThrows(IOException.class, this::createValueStore);
		assertTrue(failure.getMessage(), failure.getMessage().contains("pending retirement for active value"));
		inspectNativeStore(new File(dataDir, "values"), (stack, txn) -> {
			assertEquals("Failed validation must preserve the legacy count", 17L, nativeRefCount(stack, txn, id));
			assertMigrationMarkerAbsent(stack, txn);
			MDBStat stat = MDBStat.calloc(stack);
			E(mdb_stat(txn, openDatabaseWithTxn(txn, "unused_ids", 0), stat));
			assertEquals(1L, stat.ms_entries());
			return null;
		});
	}

	private <T> T inspectNativeStore(File directory, LmdbUtil.Transaction<T> inspection) throws IOException {
		long env;
		try (MemoryStack stack = stackPush()) {
			PointerBuffer pp = stack.mallocPointer(1);
			E(mdb_env_create(pp));
			env = pp.get(0);
		}
		try {
			E(mdb_env_set_maxdbs(env, 18));
			E(mdb_env_open(env, directory.getAbsolutePath(), MDB_NOTLS, 0664));
			return LmdbUtil.readTransaction(env, inspection);
		} finally {
			mdb_env_close(env);
		}
	}

	private void assertNativeRecordExists(MemoryStack stack, long txn, long id) throws IOException {
		MDBVal key = MDBVal.calloc(stack);
		key.mv_data(valueStore.id2data(valueStore.idBuffer(stack), id).flip());
		assertEquals(MDB_SUCCESS, mdb_get(txn, openDatabaseWithTxn(txn, null, 0), key, MDBVal.calloc(stack)));
	}

	private long nativeRefCount(MemoryStack stack, long txn, long id) throws IOException {
		MDBVal key = MDBVal.calloc(stack);
		key.mv_data(valueStore.id2data(valueStore.idBuffer(stack), id).flip());
		MDBVal data = MDBVal.calloc(stack);
		return mdb_get(txn, openDatabaseWithTxn(txn, "ref_counts", 0), key, data) == MDB_SUCCESS
				? Varint.readUnsigned(data.mv_data())
				: 0L;
	}

	private void assertMigrationMarkerAbsent(MemoryStack stack, long txn) throws IOException {
		MDBVal key = MDBVal.calloc(stack);
		key.mv_data(stack.bytes((byte) 0));
		assertNotEquals(MDB_SUCCESS,
				mdb_get(txn, openDatabaseWithTxn(txn, "ref_counts", 0), key, MDBVal.calloc(stack)));
	}

	private void replaceLegacyRefCount(long id, long count) throws IOException {
		valueStore.writeTransaction((stack, txn) -> {
			int countsDbi = openDatabaseWithTxn(txn, "ref_counts", 0);
			// Legacy stores have counts but no migration marker.
			E(mdb_drop(txn, countsDbi, false));
			if (count == 0) {
				return null;
			}
			MDBVal key = MDBVal.calloc(stack);
			key.mv_data(valueStore.id2data(valueStore.idBuffer(stack), id).flip());
			MDBVal data = MDBVal.calloc(stack);
			ByteBuffer countBuffer = stack.malloc(Long.BYTES + 1);
			Varint.writeUnsigned(countBuffer, count);
			data.mv_data(countBuffer.flip());
			E(mdb_put(txn, countsDbi, key, data, 0));
			return null;
		});
	}

	@Test
	public void testGcDatatypes() throws Exception {
		IRI[] types = new IRI[] { XSD.STRING, XSD.INTEGER, XSD.LONG, XSD.DECIMAL };
		LmdbValue[] values = new LmdbValue[types.length];
		valueStore.startTransaction(true);
		for (int i = 0; i < values.length; i++) {
			// use a value that is large enough to not being inlined
			values[i] = valueStore.createLiteral(Long.toString(Long.MAX_VALUE - 1), types[i]);
			valueStore.storeValue(values[i]);
		}
		valueStore.commit();

		valueStore.startTransaction(true);
		List<Long> datatypeIds = new LinkedList<>();
		for (int i = 0; i < types.length; i++) {
			datatypeIds.add(valueStore.storeValue(types[i]));
		}
		valueStore.commit();

		valueStore.startTransaction(true);
		valueStore.gcIds(Collections.singleton(values[0].getInternalID()), new HashSet<>());
		valueStore.gcIds(datatypeIds.subList(1, datatypeIds.size() - 1), new HashSet<>());
		valueStore.commit();

		// close and recreate store
		valueStore.close();
		valueStore = createValueStore();

		// the first value is directly GCed
		assertNull(valueStore.getValue(values[0].getInternalID()));
		// the first datatype is not directly GCed and must not be
		// removed from the store if the related literal is removed
		assertNotNull(valueStore.getValue(datatypeIds.removeFirst()));

		for (int i = 1; i < values.length; i++) {
			Value v = valueStore.getValue(values[i].getInternalID());
			IRI datatype = ((Literal) v).getDatatype();
			assertEquals(types[i], datatype);
			assertNotNull(valueStore.getValue(((LmdbValue) datatype).getInternalID()));
			datatypeIds.remove(((LmdbValue) datatype).getInternalID());
		}

		assertTrue("Datatype IDs should not have been deleted", datatypeIds.isEmpty());
	}

	@Test
	public void testGcURIs() throws Exception {
		for (boolean storeAndGcUri : List.of(false, true)) {
			valueStore.startTransaction(true);
			// use a value that is large enough to not being inlined
			LmdbLiteral literal = valueStore.createLiteral("123".repeat(5), XSD.STRING);
			valueStore.storeValue(literal);
			if (storeAndGcUri) {
				valueStore.storeValue(XSD.STRING);
			}
			valueStore.commit();

			long typeId = valueStore.getId(XSD.STRING);
			assertTrue(typeId != 0);

			Set<Long> nextGcIds = new HashSet<>();
			valueStore.startTransaction(true);
			valueStore.gcIds(Collections.singleton(literal.getInternalID()), nextGcIds);
			assertEquals(1, nextGcIds.size());
			assertTrue(nextGcIds.contains(typeId));

			if (storeAndGcUri) {
				valueStore.gcIds(nextGcIds, new HashSet<>());
			}

			valueStore.commit();

			// close and recreate store
			valueStore.close();
			valueStore = createValueStore();

			assertNull(valueStore.getValue(literal.getInternalID()));
			if (!storeAndGcUri) {
				assertNotNull(valueStore.getValue(typeId));
			} else {
				assertNull(valueStore.getValue(typeId));
			}
		}
	}

	@Test
	public void testDisableGc() throws Exception {
		final Random random = new Random(1337);
		final LmdbValue[] values = new LmdbValue[1000];

		ValueStore disabledGcValueStore = new ValueStore(
				new File(dataDir, "values"), new LmdbStoreConfig().setValueEvictionInterval(-1));
		try {
			disabledGcValueStore.startTransaction(true);
			for (int i = 0; i < values.length; i++) {
				values[i] = disabledGcValueStore.createLiteral("This is a random literal:" + random.nextLong());
				disabledGcValueStore.storeValue(values[i]);
			}
			disabledGcValueStore.commit();

			final ValueStoreRevision revBefore = disabledGcValueStore.getRevision();

			disabledGcValueStore.startTransaction(true);
			Set<Long> ids = new HashSet<>();
			for (int i = 0; i < 30; i++) {
				ids.add(values[i].getInternalID());
			}
			disabledGcValueStore.gcIds(ids, new HashSet<>());
			disabledGcValueStore.commit();

			final ValueStoreRevision revAfter = disabledGcValueStore.getRevision();

			assertEquals("revisions must NOT change since GC is disabled", revBefore, revAfter);

			Arrays.fill(values, null);
			disabledGcValueStore.unusedRevisionIds.add(revBefore.getRevisionId());

			disabledGcValueStore.forceEvictionOfValues();
			disabledGcValueStore.startTransaction(true);
			disabledGcValueStore.commit();

			disabledGcValueStore.startTransaction(true);
			for (int i = 0; i < 30; i++) {
				LmdbValue value = disabledGcValueStore.createLiteral("This is a random literal:" + random.nextLong());
				values[i] = value;
				disabledGcValueStore.storeValue(value);
				ids.remove(value.getInternalID());
			}
			disabledGcValueStore.commit();

			assertNotEquals("IDs should NOT have been reused since GC is disabled", Collections.emptySet(), ids);
		} finally {
			disabledGcValueStore.close();
			valueStore = createValueStore();
		}
	}

